package com.bank.spark.model;

// Metrics an engineer reads from the Spark UI for one stage.
public class StageMetrics {
    private final String stage;
    private final long medianTaskMs;
    private final long maxTaskMs;
    private final double gcFraction;       // GC time / task time (Executors tab)
    private final long shuffleWriteMb;     // Stages tab shuffle write

    public StageMetrics(String stage, long medianTaskMs, long maxTaskMs,
                        double gcFraction, long shuffleWriteMb) {
        this.stage = stage;
        this.medianTaskMs = medianTaskMs;
        this.maxTaskMs = maxTaskMs;
        this.gcFraction = gcFraction;
        this.shuffleWriteMb = shuffleWriteMb;
    }

    public String getStage() { return stage; }
    public long getMedianTaskMs() { return medianTaskMs; }
    public long getMaxTaskMs() { return maxTaskMs; }
    public double getGcFraction() { return gcFraction; }
    public long getShuffleWriteMb() { return shuffleWriteMb; }
}
