package com.bank.spark.service;

import com.bank.spark.model.StageMetrics;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Reads the classic Spark UI problem patterns from stage metrics.
public class UiPatternReader {

    private static final Logger log = Logger.getLogger(UiPatternReader.class.getName());
    private static final double SKEW_RATIO = 10.0;
    private static final double HIGH_GC = 0.30;
    private static final long LARGE_SHUFFLE_MB = 50_000;

    public List<String> diagnose(StageMetrics m) {
        List<String> findings = new ArrayList<>();

        // Stages tab: one task much slower than median → skew.
        if (m.getMaxTaskMs() >= SKEW_RATIO * Math.max(1, m.getMedianTaskMs())) {
            log.severe(() -> m.getStage() + ": max task " + m.getMaxTaskMs()
                    + "ms vs median " + m.getMedianTaskMs() + "ms → DATA SKEW");
            findings.add("DATA SKEW — AQE skew join / salt / isolate hot key");
        }
        // Executors tab: high GC fraction → memory pressure.
        if (m.getGcFraction() >= HIGH_GC) {
            log.warning(() -> m.getStage() + ": GC " + (int) (m.getGcFraction() * 100)
                    + "% of task time → MEMORY PRESSURE");
            findings.add("MEMORY PRESSURE — reduce caching, more partitions/memory");
        }
        // Stages tab: large shuffle write → expensive wide transformation.
        if (m.getShuffleWriteMb() >= LARGE_SHUFFLE_MB) {
            log.warning(() -> m.getStage() + ": shuffle write " + m.getShuffleWriteMb()
                    + "MB → EXPENSIVE WIDE TRANSFORMATION");
            findings.add("EXPENSIVE SHUFFLE — pre-aggregate/prune before shuffle, tune partitions");
        }
        if (findings.isEmpty()) findings.add("HEALTHY — no classic problem pattern");
        return findings;
    }
}
