package com.bank.spark;

import com.bank.spark.model.StageMetrics;
import com.bank.spark.service.UiPatternReader;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: read Spark UI patterns for several stages.
public class UiDiagnosticsDemo {

    private static final Logger log = Logger.getLogger(UiDiagnosticsDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                        new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        UiPatternReader reader = new UiPatternReader();

        List<StageMetrics> stages = List.of(
            // skew: one task 40x the median.
            new StageMetrics("join-stage", 1000, 40000, 0.05, 2000),
            // memory pressure: GC 40% of task time.
            new StageMetrics("agg-stage", 2000, 2500, 0.40, 1000),
            // expensive shuffle: 80 GB shuffle write.
            new StageMetrics("groupby-stage", 3000, 3300, 0.08, 80000),
            // healthy.
            new StageMetrics("filter-stage", 500, 550, 0.03, 100));

        for (StageMetrics m : stages) {
            List<String> findings = reader.diagnose(m);
            log.info(() -> "Stage " + m.getStage() + " → " + findings);
        }
        log.info("Spark UI diagnostics demo complete.");
    }
}
